#!/usr/bin/env python3
"""Add explicit customer cancellation confirmation to the pinned preview UI."""
import pathlib
EDITS = [('  const [selected, setSelected] = useState<MvpBooking | null>(null);', '  const [selected, setSelected] = useState<MvpBooking | null>(null);\n  const [cancelTarget, setCancelTarget] = useState<string | null>(null);'), ('    keys.current.clear();', '    setCancelTarget(null);\n    keys.current.clear();'), ('                    setSelected(b);', '                    setCancelTarget(null);\n                    setSelected(b);'), ('  async function loadBookings() {', '  async function cancelSelectedAppointment() {\n    if (mode !== "customer" || !selected || cancelTarget !== selected.id ||\n        !["PENDING", "CONFIRMED", "CHECKED_IN"].includes(selected.status) ||\n        Date.parse(selected.startsAt) <= Date.now()) return;\n    const cancelled = await api.request<MvpBooking>(\n      `/businesses/${selected.businessId}/appointments/${selected.id}/cancel`,\n      "POST",\n      { reason: "Müşteri tarafından iptal edildi." },\n    );\n    if (cancelled.id !== selected.id || cancelled.status !== "CANCELLED")\n      throw new Error("Unexpected cancellation response");\n    setSelected(cancelled);\n    setBookings((current) => current.map((item) => item.id === cancelled.id ? cancelled : item));\n    setCancelTarget(null);\n    setSlots([]);\n    setNotice("Randevunuz iptal edildi. Güncel saatler için müsaitlik aramasını yenileyin.");\n  }\n  async function loadBookings() {'), ('                {mode === "business" && (\n                  <>\n                    {[', '                {mode === "customer" &&\n                  ["PENDING", "CONFIRMED", "CHECKED_IN"].includes(selected.status) &&\n                  Date.parse(selected.startsAt) > Date.now() && (\n                    <>\n                      {cancelTarget === selected.id ? (\n                        <>\n                          <Text style={styles.body}>Bu randevuyu iptal etmek istiyor musunuz? İptal koşulları işletme tarafından kontrol edilir.</Text>\n                          {button("İptali onayla", cancelSelectedAppointment)}\n                          {button("Vazgeç", async () => { setCancelTarget(null); })}\n                        </>\n                      ) : button("Randevuyu iptal et", async () => { setCancelTarget(selected.id); })}\n                    </>\n                  )}\n                {mode === "business" && (\n                  <>\n                    {[')]
def patch(path):
    path=pathlib.Path(path)
    text=path.read_text()
    if "async function cancelSelectedAppointment()" in text: raise SystemExit("Cancellation already patched; no repeat")
    for before,after in EDITS:
        if text.count(before)!=1: raise SystemExit("Cancellation source drift; patch blocked")
        text=text.replace(before,after,1)
    path.write_text(text)
